import{_ as a,c as t,o as i,ah as n}from"./chunks/framework.DX1DJjtl.js";const p=JSON.parse('{"title":"Guides","description":"","frontmatter":{},"headers":[],"relativePath":"guides/index.md","filePath":"guides/index.md","lastUpdated":1785060787000}'),l={name:"guides/index.md"};function s(o,e,r,d,c,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h1><p>These guides teach the practical side of building CC:Tweaked interfaces with Basalt 2.5. They focus on complete tasks and the ideas behind them. For exhaustive property and method lists, use the <a href="/2.5/api/">API Reference</a>.</p><h2 id="start-here" tabindex="-1">Start Here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start Here&quot;">​</a></h2><ul><li><a href="./getting-started.html">Getting Started</a> — install Basalt and build a small interactive application.</li><li><a href="./migration-quickstart.html">Migration Quickstart</a> — port an ordinary application one working screen at a time.</li><li><a href="./migrating-from-basalt-2.html">Migration Reference</a> — look up detailed mappings for plugins, layout, state, XML, themes, and removed systems.</li></ul><h2 id="foundations" tabindex="-1">Foundations <a class="header-anchor" href="#foundations" aria-label="Permalink to &quot;Foundations&quot;">​</a></h2><p>Read these guides in order when learning Basalt:</p><ol><li><a href="./foundations/installation.html">Installation</a> — choose a build, install it, and verify your setup.</li><li><a href="./foundations/mental-model.html">How Basalt Works</a> — understand frames, element trees, rendering, and the event loop.</li><li><a href="./foundations/elements-and-properties.html">Elements and Properties</a> — create, configure, find, hide, disable, and remove elements.</li><li><a href="./foundations/events-and-focus.html">Events and Focus</a> — respond to mouse and keyboard input.</li><li><a href="./foundations/layout-basics.html">Layout Basics</a> — combine fixed sizes with <code>auto</code>, <code>fill</code>, and percentage-based sizing.</li><li><a href="./foundations/flex-layouts.html">Flex Layouts</a> — build rows, columns, toolbars, sidebars, and resizable application shells.</li><li><a href="./foundations/reactive-state.html">Reactive State</a> — connect application data to the interface with signals, computed values, and bindings.</li><li><a href="./foundations/styling-states-and-themes.html">Styling, States, and Themes</a> — use RGB colors, interaction states, reusable defaults, presets, and external theme files.</li></ol><h2 id="building-interfaces" tabindex="-1">Building Interfaces <a class="header-anchor" href="#building-interfaces" aria-label="Permalink to &quot;Building Interfaces&quot;">​</a></h2><ul><li><a href="./building-interfaces/text-inputs.html">Text Inputs</a> — handle one-line and multiline editing, events, Enter, and focus.</li><li><a href="./building-interfaces/form-controls-and-validation.html">Form Controls and Validation</a> — combine toggles, sliders, reactive values, validation, and submission.</li><li><a href="./building-interfaces/lists-and-selection.html">Lists and Selection</a> — manage visible rows, scrolling, selection, activation, and multiple selection.</li><li><a href="./building-interfaces/dropdowns-and-suggestions.html">Dropdowns and Suggestions</a> — build compact fixed choices and editable suggestion fields.</li><li><a href="./building-interfaces/tables-and-trees.html">Tables and Trees</a> — present, sort, filter, select, and navigate tabular and hierarchical data.</li><li><a href="./building-interfaces/page-navigation.html">Page Navigation</a> — switch persistent application pages and manage route focus.</li><li><a href="./building-interfaces/tabs.html">Tabs</a> — organize related views inside one persistent panel.</li><li><a href="./building-interfaces/feedback-and-progress.html">Feedback and Progress</a> — show inline status, Toast notifications, and determinate progress.</li><li><a href="./building-interfaces/dialogs.html">Dialogs and Context Menus</a> — interrupt a workflow for decisions, prompts, or temporary actions.</li><li><a href="./building-interfaces/canvas.html">Canvas</a> — paint dense custom surfaces.</li><li><a href="./building-interfaces/hosted-programs.html">Hosted Programs</a> — run complete CC programs inside a Basalt interface.</li><li><a href="./building-interfaces/multiple-roots-and-monitors.html">Multiple Roots and Monitors</a> — coordinate terminal and monitor UI trees through one event loop and a shared application model.</li></ul><h2 id="optional-modules" tabindex="-1">Optional Modules <a class="header-anchor" href="#optional-modules" aria-label="Permalink to &quot;Optional Modules&quot;">​</a></h2><ul><li><a href="./modules/">Using Optional Modules</a> — choose and load only the features an application needs.</li><li><a href="./modules/animation-and-responsive.html">Animation and Responsive Layouts</a> — tween properties and apply breakpoint styles.</li><li><a href="./modules/charts-images-and-bigfont.html">Charts, Images, and BigFont</a> — visualize data, load assets, and display large text.</li></ul><h2 id="application-recipes" tabindex="-1">Application Recipes <a class="header-anchor" href="#application-recipes" aria-label="Permalink to &quot;Application Recipes&quot;">​</a></h2><ul><li><a href="./recipes/control-room-dashboard.html">Control Room Dashboard</a> — combine a shared data model, persistent pages, a sortable table, reactive settings, dialogs, toasts, and scheduled chart updates in one complete application.</li></ul><h2 id="xml" tabindex="-1">XML <a class="header-anchor" href="#xml" aria-label="Permalink to &quot;XML&quot;">​</a></h2><ul><li><a href="./xml/">XML Interfaces</a> — understand Basalt&#39;s XML subset, element mapping, attributes, handler scopes, reactive expressions, and limitations.</li><li><a href="./xml/building-with-xml.html">Building Interfaces with XML</a> — build, connect, populate, reload, and test a complete file-backed interface.</li></ul><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><ul><li><a href="./development/interactive-examples.html">Interactive Examples</a> — run Basalt and CC:Tweaked examples directly in the browser.</li><li><a href="./development/debugging.html">Debugging</a> — inspect live interfaces and understand error screens.</li><li><a href="./development/testing.html">Testing</a> — assert state, focus, hit testing, and event routing without a blocking loop.</li><li><a href="./development/performance-tuning.html">Performance Tuning</a> — measure realistic updates, understand invalidation and line-based flushing, and reduce layout, rendering, and reactive work.</li></ul><h2 id="guide-coverage" tabindex="-1">Guide Coverage <a class="header-anchor" href="#guide-coverage" aria-label="Permalink to &quot;Guide Coverage&quot;">​</a></h2><p>The planned core guide path is complete. Future additions can focus on project-specific recipes, persistence, networking, and deployment patterns.</p><p>The guide set follows the current Basalt 2.5 source. Documentation for the frozen Basalt 2 release remains available in the <a href="https://basalt.madefor.cc/2.0/" target="_blank" rel="noreferrer">Basalt 2 documentation</a>.</p>',20)])])}const m=a(l,[["render",s]]);export{p as __pageData,m as default};
